"use strict";

require("webroot/vendor/pages/common/js/checkUserActivity-es6");

angular
	.module("irtech.netcity.school.ndconstructor")
	.controller("ndconstructorCtrl", ($scope, $http, $document, $location, $appLoader, settingsProvider, $sce) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kIntegrationNewDiskConstructor,
			back: { history: true }
		}

		$.extend($scope, {
			url: ""
		});

		$scope.trustSrc = function (src) {
			return $sce.trustAsResourceUrl(src);
		}

		//загрузка данных
		$scope.load = () => {
			$appLoader.show();
			$http.get(`/webapi/newDiskConstructor/get`)
				.then((result) => {
					$scope.url = result.data;
					$scope.$applyAsync(() => {
						$appLoader.hide();
					});
				})
				.catch(() => $appLoader.hide());
		}

		$(function () {
			var frameElement = document.getElementById('apps-iframe');

			function postMessageHandler(e) {
				var message, height;

				if (e.data) {
					try {
						message = JSON.parse(e.data);

						if (message.onresize && message.onresize.height) {
							height = message.onresize.height;

							if (height) {
								height = height > window.innerHeight ? height : window.innerHeight;

								setTimeout(() => {
									frameElement.style.height = height + 'px';
								}, 100);
							}
						}
					} catch (e) {
						console.dir(e);
					}
				}
			}

			if (window.addEventListener) {
				window.addEventListener('message', postMessageHandler);
			} else {
				window.attachEvent('onmessage', postMessageHandler);
			}

			function frameScrollTopHandler() {
				var scrollTop = $(window).scrollTop() - frameElement.getBoundingClientRect().top;
				frameElement.contentWindow.postMessage({ scrollTop: scrollTop }, $scope.url);
			}

			$(window).resize(frameScrollTopHandler);
			$(window).scroll(frameScrollTopHandler);
		});

		$scope.load();
	});



