const module = angular.module("irtech.netcity.school.ndconstructor",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("./index/ndconstructorCtrl.js");

module
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.otherwise({
				templateUrl: "/static/dist/app/school/ndconstructor/index/template.html",
				controller: "ndconstructorCtrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});


